package com.isoform

import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReadableArray
import com.facebook.react.module.annotations.ReactModule

/**
 * TurboModule behind `prefetchImages` and `clearImageCache`. `NativeIsoImageModuleSpec`
 * is generated by Codegen from `src/adapters/react-native/image/native/NativeIsoImageModule.ts`.
 */
@ReactModule(name = IsoImageModule.NAME)
class IsoImageModule(context: ReactApplicationContext) : NativeIsoImageModuleSpec(context) {
  init {
    IsoImagePipeline.init(context)
  }

  override fun getName(): String = NAME

  override fun prefetch(urls: ReadableArray, headers: ReadableArray, memory: Boolean, disk: Boolean, promise: Promise) {
    val uris = (0 until urls.size()).mapNotNull { urls.getString(it) }
    val flat = (0 until headers.size()).mapNotNull { headers.getString(it) }
    IsoImagePipeline.prefetch(uris, headerMap(flat), memory, disk) { promise.resolve(it) }
  }

  override fun clear(memory: Boolean, disk: Boolean, promise: Promise) {
    IsoImagePipeline.clear(memory, disk) { promise.resolve(null) }
  }

  companion object {
    const val NAME = "IsoImageModule"
  }
}
